const form = document.getElementById("inscricao");
const nome = document.getElementById("nome");
const tema = document.getElementById("tema");
const outroTema = document.getElementById("outro-tema");
const regras = document.getElementById("regras");
const enviar = document.getElementById("enviar");
const mensagem = document.getElementById("mensagem");

// Mostra o campo extra só quando o tema é "Outro"
tema.addEventListener("change", () => {
  outroTema.style.display = tema.value === "Outro" ? "block" : "none";
});

// O botão só libera com as regras lidas
regras.addEventListener("change", () => {
  enviar.disabled = !regras.checked;
});

// Tira o destaque de erro enquanto a pessoa corrige o nome
nome.addEventListener("input", () => {
  nome.classList.remove("campo-erro");
});

form.addEventListener("submit", (e) => {
  e.preventDefault();
  mensagem.className = "erro";

  if (nome.value.trim().length < 3) {
    nome.classList.add("campo-erro");
    mensagem.textContent = "Digite seu nome (pelo menos 3 letras).";
    return;
  }
  if (tema.value === "") {
    mensagem.textContent = "Escolha um tema.";
    return;
  }
  if (tema.value === "Outro" && outroTema.value.trim() === "") {
    mensagem.textContent = "Conte qual tema você quer.";
    return;
  }

  const temaFinal = tema.value === "Outro" ? outroTema.value.trim() : tema.value;
  mensagem.className = "ok";
  mensagem.textContent = `Inscrição confirmada, ${nome.value.trim()}! Tema: ${temaFinal}.`;

  form.reset();
  outroTema.style.display = "none";
  enviar.disabled = true;
});

