  paragrafo.textContent = "Texto alterado pelo JavaScript!";
});

const mais = document.getElementById("mais");
const placar = document.getElementById("placar");
let cliques = 0;

mais.addEventListener("click", () => {
  cliques++;
  placar.textContent = "Cliques: " + cliques;
});

const tema = document.getElementById("tema");

tema.addEventListener("click", () => {
  document.body.classList.toggle("escuro");
  if (document.body.classList.contains("escuro")) {
    tema.textContent = "Modo claro";
  } else {
    tema.textContent = "Modo escuro";
  }
});

const campo = document.getElementById("campo");
const espelho = document.getElementById("espelho");

campo.addEventListener("input", () => {
  espelho.textContent = campo.value.toUpperCase();
});

const formImc = document.getElementById("imc");
const peso = document.getElementById("peso");
const altura = document.getElementById("altura");
const resultado = document.getElementById("resultado");

formImc.addEventListener("submit", (e) => {
  e.preventDefault();
  if (peso.value === "" || altura.value === "") {
    resultado.textContent = "Preencha peso e altura.";
    return;
  }
  const p = Number(peso.value);
  const a = Number(altura.value);
  const imc = p / (a * a);
  resultado.textContent = `Seu IMC é ${imc.toFixed(1)}`;
});

const sabor = document.getElementById("sabor");
const total = document.getElementById("total");

sabor.addEventListener("change", () => {
  if (sabor.value === "") {
    total.textContent = "";
    return;
  }
  total.textContent = `Total: R$ ${Number(sabor.value)},00`;
});

const login = document.getElementById("login");
const usuario = document.getElementById("usuario");
const senha = document.getElementById("senha");
const entrar = document.getElementById("entrar");
const saudacao = document.getElementById("saudacao");

function verificar() {
  const usuarioOk = usuario.value.trim().length >= 3;
  const senhaOk = senha.value.length >= 6;
  entrar.disabled = !(usuarioOk && senhaOk);
}

usuario.addEventListener("input", verificar);
senha.addEventListener("input", verificar);

login.addEventListener("submit", (e) => {
  e.preventDefault();
  saudacao.textContent = `Bem-vindo(a), ${usuario.value.trim()}!`;
});

